<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!collector_marketplace_ready())redirect('upgrade-collector-marketplace.php');$id=(int)($_GET['id']??0);$p=db()->prepare('SELECT * FROM collector_profiles WHERE id=?');$p->execute([$id]);$p=$p->fetch();if(!$p||!can_manage_collector($p)){http_response_code(403);exit('You cannot manage this collector profile.');}$tab=$_GET['tab']??'overview';$allowed=['overview','profile','items','offers','favorites','settings'];if(!in_array($tab,$allowed,true))$tab='overview';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='save_profile'){$avatar=save_uploaded_image('avatar','collectors/avatars',$id);$banner=save_uploaded_image('banner','collectors/banners',$id);$sql='UPDATE collector_profiles SET shop_name=?,slug=?,tagline=?,bio=?,location=?,website=?'.($avatar?',avatar_path=?':'').($banner?',banner_path=?':'').' WHERE id=?';$a=[trim($_POST['shop_name']),collector_slug(trim($_POST['shop_name']),$id),trim($_POST['tagline']),trim($_POST['bio']),trim($_POST['location']),trim($_POST['website'])];if($avatar)$a[]=$avatar;if($banner)$a[]=$banner;$a[]=$id;db()->prepare($sql)->execute($a);flash('success','Collector profile saved.');$tab='profile';}elseif($action==='save_item'){$iid=(int)($_POST['item_id']??0);$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Item title is required.');$img=save_uploaded_image('image','collectors/items',$iid?:$id);$vals=[$title,collector_item_slug($title,$iid),$_POST['listing_type']??'sale',$_POST['category']??'other',trim($_POST['franchise']??''),trim($_POST['description']??''),trim($_POST['condition_grade']??''),($_POST['price']??'')!==''?(float)$_POST['price']:null,max(1,(int)($_POST['quantity']??1)),$_POST['status']??'draft'];if($iid){$sql='UPDATE collector_items SET title=?,slug=?,listing_type=?,category=?,franchise=?,description=?,condition_grade=?,price=?,quantity=?,status=?'.($img?',image_path=?':'').' WHERE id=? AND collector_id=?';if($img)$vals[]=$img;$vals[]=$iid;$vals[]=$id;db()->prepare($sql)->execute($vals);}else{db()->prepare('INSERT INTO collector_items(collector_id,title,slug,listing_type,category,franchise,description,condition_grade,price,quantity,status,image_path) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute(array_merge([$id],$vals,[$img]));}flash('success','Item saved.');$tab='items';}elseif($action==='delete_item'){db()->prepare('DELETE FROM collector_items WHERE id=? AND collector_id=?')->execute([(int)$_POST['item_id'],$id]);flash('success','Item deleted.');$tab='items';}elseif($action==='update_offer'){$status=$_POST['status']??'pending';db()->prepare('UPDATE collector_offers o JOIN collector_items i ON i.id=o.item_id SET o.status=?,o.seller_note=? WHERE o.id=? AND i.collector_id=?')->execute([$status,trim($_POST['seller_note']??''),(int)$_POST['offer_id'],$id]);flash('success','Offer updated.');$tab='offers';}elseif($action==='save_settings'){$status=$p['status'];if((user()['role']??'')==='admin')$status=$_POST['status']??$status;db()->prepare('UPDATE collector_profiles SET status=?,is_featured=? WHERE id=?')->execute([$status,((user()['role']??'')==='admin'&&isset($_POST['is_featured']))?1:0,$id]);flash('success','Settings saved.');$tab='settings';}}catch(Throwable $e){flash('error',$e->getMessage());}redirect_route('collectors/manage.php',['id'=>$id,'tab'=>$tab]);}$p=db()->prepare('SELECT * FROM collector_profiles WHERE id=?');$p->execute([$id]);$p=$p->fetch();$items=db()->prepare('SELECT * FROM collector_items WHERE collector_id=? ORDER BY created_at DESC');$items->execute([$id]);$items=$items->fetchAll();$offers=db()->prepare('SELECT o.*,i.title,u.display_name buyer_name FROM collector_offers o JOIN collector_items i ON i.id=o.item_id JOIN users u ON u.id=o.buyer_user_id WHERE i.collector_id=? ORDER BY o.created_at DESC');$offers->execute([$id]);$offers=$offers->fetchAll();app_header('Manage '.$p['shop_name']);?><section class="dashboard-hero"><p class="eyebrow">COLLECTOR MANAGEMENT</p><h1><?=e($p['shop_name'])?></h1><p>Manage your collection, listings, offers, and marketplace profile.</p><p><a class="button ghost" href="view.php?slug=<?=urlencode($p['slug'])?>">View Public Profile</a></p></section><nav class="management-tabs"><?php foreach(['overview'=>'Overview','profile'=>'Profile','items'=>'Collection & Listings','offers'=>'Offers','favorites'=>'Favorites','settings'=>'Settings'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?id=<?=$id?>&tab=<?=$k?>"><?=$v?></a><?php endforeach?></nav><?php if($tab==='overview'):?><section class="dev-stat-grid"><article class="app-card dev-stat"><span>Items</span><strong><?=count($items)?></strong></article><article class="app-card dev-stat"><span>Active</span><strong><?=count(array_filter($items,fn($x)=>$x['status']==='active'))?></strong></article><article class="app-card dev-stat"><span>Offers</span><strong><?=count($offers)?></strong></article><article class="app-card dev-stat"><span>Pending offers</span><strong><?=count(array_filter($offers,fn($x)=>$x['status']==='pending'))?></strong></article></section><?php elseif($tab==='profile'):?><section class="form-card wide"><h2>Collector Profile</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_profile"><label>Shop name<input name="shop_name" value="<?=e($p['shop_name'])?>" required></label><label>Tagline<input name="tagline" value="<?=e($p['tagline'])?>"></label><label>Location<input name="location" value="<?=e($p['location'])?>"></label><label>Website<input name="website" value="<?=e($p['website'])?>"></label><label>Avatar<input type="file" name="avatar" accept="image/*"></label><label>Banner<input type="file" name="banner" accept="image/*"></label><label class="full">Bio<textarea name="bio" rows="7"><?=e($p['bio'])?></textarea></label><button class="button primary">Save Profile</button></form></section><?php elseif($tab==='items'):?><section class="form-card wide"><h2>Add Item</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_item"><label>Title<input name="title" required></label><label>Listing type<select name="listing_type"><?php foreach(collector_listing_types() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Category<select name="category"><?php foreach(collector_categories() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Franchise<input name="franchise"></label><label>Condition / grade<input name="condition_grade" placeholder="Near Mint, CGC 9.8, Complete..."></label><label>Price<input type="number" min="0" step="0.01" name="price"></label><label>Quantity<input type="number" min="1" name="quantity" value="1"></label><label>Status<select name="status"><option value="draft">Draft</option><option value="active">Active</option><option value="reserved">Reserved</option><option value="sold">Sold</option><option value="traded">Traded</option><option value="archived">Archived</option></select></label><label>Image<input type="file" name="image" accept="image/*"></label><label class="full">Description<textarea name="description"></textarea></label><button class="button primary">Save Item</button></form></section><section class="admin-table-wrap"><table><thead><tr><th>Item</th><th>Type</th><th>Status</th><th>Price</th><th>Action</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><a href="item.php?slug=<?=urlencode($i['slug'])?>"><?=e($i['title'])?></a></td><td><?=e(collector_listing_types()[$i['listing_type']]??$i['listing_type'])?></td><td><?=e($i['status'])?></td><td><?=$i['price']!==null?'$'.number_format((float)$i['price'],2):'—'?></td><td><form method="post" onsubmit="return confirm('Delete this item?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_item"><input type="hidden" name="item_id" value="<?=$i['id']?>"><button class="button danger">Delete</button></form></td></tr><?php endforeach?></tbody></table></section><?php elseif($tab==='offers'):?><section class="stack"><?php foreach($offers as $o):?><article class="app-card"><h2><?=e($o['title'])?></h2><p><strong><?=e($o['buyer_name'])?></strong> · <?=e(ucfirst($o['offer_type']))?><?php if($o['amount']!==null):?> · $<?=number_format((float)$o['amount'],2)?><?php endif?></p><p><?=nl2br(e($o['message']))?></p><p><?=nl2br(e($o['trade_details']))?></p><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="update_offer"><input type="hidden" name="offer_id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','accepted','declined','withdrawn','completed'] as $st):?><option value="<?=$st?>" <?=$o['status']===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach?></select><input name="seller_note" value="<?=e($o['seller_note'])?>" placeholder="Private seller note"><button>Update</button></form></article><?php endforeach?><?php if(!$offers):?><div class="empty-state"><h2>No offers yet</h2></div><?php endif?></section><?php elseif($tab==='favorites'):$fs=db()->prepare('SELECT i.*,cp.shop_name FROM collector_favorites f JOIN collector_items i ON i.id=f.item_id JOIN collector_profiles cp ON cp.id=i.collector_id WHERE f.user_id=? ORDER BY f.created_at DESC');$fs->execute([(int)user()['id']]);?><section class="collector-grid"><?php foreach($fs->fetchAll() as $i):?><article class="collector-card"><div class="collector-card-body"><h2><a href="item.php?slug=<?=urlencode($i['slug'])?>"><?=e($i['title'])?></a></h2><p><?=e($i['shop_name'])?></p></div></article><?php endforeach?></section><?php elseif($tab==='settings'):?><section class="form-card"><h2>Marketplace Settings</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><?php if((user()['role']??'')==='admin'):?><label>Status<select name="status"><?php foreach(['pending','approved','suspended'] as $st):?><option value="<?=$st?>" <?=$p['status']===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach?></select></label><label><input type="checkbox" name="is_featured" <?=$p['is_featured']?'checked':''?>> Featured collector</label><?php else:?><p>Approval status: <span class="badge"><?=e(ucfirst($p['status']))?></span></p><?php endif?><button class="button primary">Save Settings</button></form></section><?php endif;app_footer();
